import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { getMeetings, updateMeetingStatus } from '../../api';

function HodDashboard({ user }) {
  const [meetings, setMeetings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [msg, setMsg] = useState('');

  useEffect(() => { load(); }, []);

  const load = async () => {
    try { const r = await getMeetings(); setMeetings(r.data); }
    catch (e) { console.error(e); }
    finally { setLoading(false); }
  };

  const flash = (m) => { setMsg(m); setTimeout(() => setMsg(''), 3000); };

  const handleStatus = async (id, status) => {
    try { await updateMeetingStatus(id, status); flash(`✅ Meeting marked as ${status}`); load(); }
    catch (e) { flash('❌ Failed'); }
  };

  const today = new Date().toDateString();
  const todayMeetings = meetings.filter(m => new Date(m.date).toDateString() === today);
  const upcoming = meetings.filter(m => m.status === 'scheduled' && new Date(m.date) >= new Date());
  const completed = meetings.filter(m => m.status === 'completed');

  if (loading) return <div className="loading">Loading...</div>;

  return (
    <div className="bg-wrapper">
      <div className="bg-content">
        <h1 className="page-title text-green">HOD Dashboard</h1>
        {msg && <div className={`alert ${msg.includes('❌') ? 'alert-error' : 'alert-success'}`}>{msg}</div>}

        <div className="stat-grid">
          <div className="stat-card">
            <div className="stat-label">Today's Meetings</div>
            <div className="stat-num">{todayMeetings.length}</div>
          </div>
          <div className="stat-card">
            <div className="stat-label">Upcoming</div>
            <div className="stat-num blue">{upcoming.length}</div>
          </div>
          <div className="stat-card">
            <div className="stat-label">Completed</div>
            <div className="stat-num blue">{completed.length}</div>
          </div>
        </div>

        <div className="card">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
            <h2 style={{ margin: 0 }}>Upcoming Meetings</h2>
            <Link to="/hod/schedule">
              <button className="btn btn-teal btn-sm">+ Add Availability</button>
            </Link>
          </div>

          {meetings.length === 0 ? (
            <p style={{ color: '#6b7280', textAlign: 'center', padding: '2rem' }}>No meetings yet.</p>
          ) : (
            <table>
              <thead style={{ background: '#e0f2e9' }}>
                <tr><th>Staff / Scheduled By</th><th>Date</th><th>Time</th><th>Agenda</th><th>Status</th><th>Review</th></tr>
              </thead>
              <tbody>
                {meetings.map(m => (
                  <tr key={m._id}>
                    <td>{m.scheduledBy?.name === user.name ? m.attendees?.map(a => a.user?.name).join(', ') || '—' : m.scheduledBy?.name}</td>
                    <td>{new Date(m.date).toLocaleDateString('en-IN')}</td>
                    <td>{m.time}</td>
                    <td>{m.agenda || m.title}</td>
                    <td><span className={`badge badge-${m.status}`}>{m.status}</span></td>
                    <td>
                      {m.status === 'scheduled' && m.scheduledBy?._id === user.id && (
                        <button className="btn btn-teal btn-sm" onClick={() => handleStatus(m._id, 'completed')}>Done</button>
                      )}
                      {m.status === 'completed' && <span style={{ color: '#16a34a' }}>✓ Done</span>}
                      {m.meetingLink && m.status === 'scheduled' && (
                        <a href={m.meetingLink} target="_blank" rel="noreferrer">
                          <button className="btn btn-primary btn-sm" style={{ marginLeft: '0.3rem' }}>Join</button>
                        </a>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}

export default HodDashboard;
